from bcc import BPF, USDT, bcc_symbol, find_library
import ctypes as ct
import time
import sys
import os

# BPF program for counting strlen return values
bpf_text_count = """
BPF_HISTOGRAM(ret_hist);

int count_strlen_ret(struct pt_regs *ctx) {
    int ret = PT_REGS_RC(ctx);
    ret_hist.increment(ret);
    return 0;
}
"""

# BPF program for submitting resolver and implementation addresses
bpf_text_submit = """
BPF_PERF_OUTPUT(events);

struct data_t {
    u64 resolver_addr;
    u64 impl_addr;
};

int submit_addrs(struct pt_regs *ctx) {
    struct data_t data = {};
    data.resolver_addr = (u64)PT_REGS_PARM1(ctx);
    data.impl_addr = (u64)PT_REGS_PARM2(ctx);
    events.perf_submit(ctx, &data, sizeof(data));
    return 0;
}
"""

def get_strlen_symbol():
    libc_path = find_library("c")
    if not libc_path:
        raise RuntimeError("Could not find libc")
    syms = []
    bcc_symbol.foreach_symbol(libc_path, lambda sym: syms.append(sym))
    for sym in syms:
        if sym.name == "strlen":
            return libc_path, sym
    raise RuntimeError("Could not find strlen symbol in libc")

def set_resolver_and_impl_addrs(bpf, resolver_addr, impl_addr):
    bpf["resolver_addr"][ct.c_int(0)] = ct.c_ulonglong(resolver_addr)
    bpf["impl_addr"][ct.c_int(0)] = ct.c_ulonglong(impl_addr)

def find_impl_offset(libc_path, resolver_addr):
    syms = []
    bcc_symbol.foreach_symbol(libc_path, lambda sym: syms.append(sym))
    for sym in syms:
        if sym.addr == resolver_addr:
            # Try to find the next function after resolver
            idx = syms.index(sym)
            if idx + 1 < len(syms):
                impl_sym = syms[idx + 1]
                return impl_sym.addr - resolver_addr, impl_sym
    raise RuntimeError("Could not find implementation offset")

def main():
    libc_path, strlen_sym = get_strlen_symbol()
    resolver_addr = strlen_sym.addr
    impl_offset, impl_sym = find_impl_offset(libc_path, resolver_addr)
    impl_addr = resolver_addr + impl_offset

    # Load BPF program for counting
    bpf = BPF(text=bpf_text_count)
    # Attach to implementation function
    bpf.attach_uprobe(name=libc_path, sym=impl_sym.name, fn_name="count_strlen_ret", retprobe=True)

    print("Tracing strlen return values... Hit Ctrl-C to end.")

    try:
        while True:
            time.sleep(1)
            print("Histogram of strlen return values:")
            bpf["ret_hist"].print_log2_hist("strlen return")
            bpf["ret_hist"].clear()
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()
